#include <iostream>
using namespace std;

struct Node {
    int data;
    Node* left;
    Node* right;
    Node(int d) : data(d), left(nullptr), right(nullptr) {}
};

Node* insert(Node* node, int value) {
    if (node == nullptr) {
        return new Node(value);
    }
    if (value < node->data) {
        node->left = insert(node->left, value);
    } else {
        node->right = insert(node->right, value);
    }
    return node;
}

Node* findMin(Node* node) {
    while (node->left != nullptr) {
        node = node->left;
    }
    return node;
}

Node* findMax(Node* node) {
    while (node->right != nullptr) {
        node = node->right;
    }
    return node;
}

Node* successor(Node* root, Node* target) {
    if (target->right != nullptr) {
        return findMin(target->right);
    }
    Node* succ = nullptr;
    Node* cur = root;
    while (cur != target) {
        if (target->data < cur->data) {
            succ = cur;
            cur = cur->left;
        } else {
            cur = cur->right;
        }
    }
    return succ;
}

void destroy(Node* node) {
    if (node == nullptr) {
        return;
    }
    destroy(node->left);
    destroy(node->right);
    delete node;
}

int main() {
    Node* root = nullptr;
    int values[] = {50, 30, 70, 20, 40, 60, 80};
    for (int i = 0; i < 7; i++) {
        root = insert(root, values[i]);
    }
    cout << "Smallest: " << findMin(root)->data << endl;
    cout << "Largest: " << findMax(root)->data << endl;
    Node* thirty = root->left;
    Node* forty = thirty->right;
    cout << "After 30 comes " << successor(root, thirty)->data << endl;
    cout << "After 40 comes " << successor(root, forty)->data << endl;
    destroy(root);
    return 0;
}
